import{createCrossChannelToFn,toCrossChannelTargets}from"#channel/cross-channel-receive.js";import{ContextContainer,contextStorage}from"#context/container.js";import{createWorkflowRuntime}from"#execution/workflow-runtime.js";function createToolChannelTo(e){return(t,n)=>{if(e.delegated)throw Error(`ctx.to() isn't available in a delegated session (a subagent, a root copy, or a remote agent call): a session it started would outlive the delegation and act for the caller. Return the result to the caller, and send from a tool on the root agent.`);return{async send(r,i){let a=await e.loadBundle(),o=createCrossChannelToFn(createWorkflowRuntime({compiledArtifactsSource:a.compiledArtifactsSource}),toCrossChannelTargets(a.graph.root.channels));return await contextStorage.run(new ContextContainer,()=>o(t,n).send(r,i))}}}}export{createToolChannelTo};